 if($a==='now'){$m=gszDatabaseBackup($pdo,'manuell');gszAudit($pdo,$admin,'backup_created',['file'=>$m['file'],'sha256'=>$m['sha256']]);gszBackupPrune($pdo);$_SESSION['app_notice']='Sicherung erstellt – jetzt herunterladen.';}
